package demo;

import net.minecraft.world.DifficultyInstance;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.entity.MobSpawnType;
import net.minecraft.world.entity.SpawnGroupData;
import net.minecraft.world.level.ServerLevelAccessor;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.EventHooks;
import net.neoforged.neoforge.event.entity.EntityJoinLevelEvent;
import net.neoforged.neoforge.event.entity.living.MobSpawnEvent;

@EventBusSubscriber(modid = "demo")
public final class SpawnHooks {
	@SubscribeEvent
	public static void onJoin(EntityJoinLevelEvent event) {
		if (!event.loadedFromDisk() && event.getEntity() instanceof Mob mob) mob.setPersistenceRequired();
	}

	@SubscribeEvent
	public static void onPosition(MobSpawnEvent.PositionCheck event) {
		if (event.getSpawnType() == MobSpawnType.NATURAL && event.getY() < 0) event.setResult(MobSpawnEvent.PositionCheck.Result.FAIL);
	}

	public static boolean allowed(Mob mob, ServerLevelAccessor level, MobSpawnType type) {
		MobSpawnEvent.PositionCheck event = new MobSpawnEvent.PositionCheck(mob, level, type, null);
		NeoForge.EVENT_BUS.post(event);
		return event.getResult() != MobSpawnEvent.PositionCheck.Result.FAIL;
	}

	public static SpawnGroupData finish(Mob mob, ServerLevelAccessor level, DifficultyInstance difficulty, MobSpawnType type, SpawnGroupData data) {
		return EventHooks.finalizeMobSpawn(mob, level, difficulty, type, data);
	}
}

