import net.neoforged.neoforge.common.util.BlockSnapshot;
import net.neoforged.neoforge.event.EventHooks;
import net.neoforged.neoforge.event.entity.EntityMobGriefingEvent;
import net.neoforged.neoforge.event.entity.living.LivingDestroyBlockEvent;

@EventBusSubscriber(modid = "demo")
public final class GriefHooks {
	@SubscribeEvent
	public static void onGrief(EntityMobGriefingEvent event) {
		if (event.getEntity() instanceof Zombie) event.setCanGrief(true);
	}

	@SubscribeEvent
	public static void onDestroy(LivingDestroyBlockEvent event) {
		if (event.getState().getLightEmission(event.getEntity().level(), event.getPos()) > 0) event.setCanceled(true);
	}

	public static boolean canBreak(ServerLevel level, BlockPos pos, Zombie zombie, boolean rules) {
		if (rules) return CommonHooks.canEntityDestroy(level, pos, zombie);
		BlockState state = level.getBlockState(pos);
		return state.canEntityDestroy(level, pos, zombie) && EventHooks.onEntityDestroyBlock(zombie, pos, state);
	}

	public static boolean canPlace(ServerLevel level, BlockPos pos, Zombie zombie, Direction face) {
		return EventHooks.canEntityGrief(level, zombie) && !EventHooks.onBlockPlace(zombie, BlockSnapshot.create(level.dimension(), level, pos), face);
	}

	public static EquipmentSlot slot(ItemStack stack) {
		EquipmentSlot slot = stack.getEquipmentSlot();
		return slot != null ? slot : EquipmentSlot.MAINHAND;
	}
}

