package demo;

import java.util.UUID;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.common.UsernameCache;
import net.neoforged.neoforge.common.util.FakePlayer;
import net.neoforged.neoforge.common.util.FakePlayerFactory;
import net.neoforged.neoforge.common.util.ValueIOSerializable;
import net.neoforged.neoforge.entity.IEntityWithComplexSpawn;
import net.neoforged.neoforge.network.codec.NeoForgeStreamCodecs;

public class Helpers implements IEntityWithComplexSpawn, ValueIOSerializable {
	public enum Mode {
		ON,
		OFF
	}

	public static final StreamCodec<FriendlyByteBuf, Mode> MODE = NeoForgeStreamCodecs.enumCodec(Mode.class);
	private int value;

	public static String owner(UUID id) {
		return UsernameCache.getLastKnownUsername(id);
	}

	public static FakePlayer machine(ServerLevel level) {
		return FakePlayerFactory.getMinecraft(level);
	}

	@Override
	public void writeSpawnData(RegistryFriendlyByteBuf buffer) {
		buffer.writeVarInt(value);
	}

	@Override
	public void readSpawnData(RegistryFriendlyByteBuf buffer) {
		value = buffer.readVarInt();
	}

	@Override
	public void serialize(ValueOutput output) {
		output.putInt("value", value);
	}

	@Override
	public void deserialize(ValueInput input) {
		value = input.getIntOr("value", 0);
	}
}

