public final class Mods {
	static int plugins(Class<? extends java.lang.annotation.Annotation> marker) {
		int found = 0;
		for (ModContainer container : ModList.get().getSortedMods()) {
			IModFileInfo file = container.getModInfo().getOwningFile();
			if (file != null) found += (int) file.getFile().getScanResult().getAnnotatedBy(marker, ElementType.TYPE).count();
		}
		return found;
	}

	static String version(String modid) {
		return ModList.get().getModContainerById(modid).map(c -> MavenVersionTranslator.artifactVersionToString(c.getModInfo().getVersion())).orElse("");
	}

	static boolean loading(String modid) {
		return FMLLoader.getCurrent().getLoadingModList().getModFileById(modid) != null;
	}

	static boolean has(DataComponentMap.Builder builder, DataComponentType<?> type) {
		return builder.has(type);
	}

	static void send(ServerPlayer player, CustomPacketPayload payload) {
		player.connection.send(payload);
	}

	static Entity parent(Entity entity) {
		return entity.isMultipartEntity() && entity instanceof PartEntity<?> part ? part.getParent() : entity;
	}

	static Object name(Object value) {
		return value instanceof TranslatableEnum e ? e.getTranslatedName() : ItemAbilities.SHEARS_DIG.name();
	}
}

