		Identifier.fromNamespaceAndPath("demo", "got_note"),
		builder -> builder.initializer(() -> false).persistent(Codec.BOOL).copyOnDeath()
	);

	public static void init(ModConfigSpec spec) {
		ModConfigEvents.loading("demo").register(config -> spec.afterReload());
		ConfigRegistry.INSTANCE.register("demo", ModConfig.Type.LOCAL, spec);
	}

	static void join(ServerPlayer player) {
		if (!AttachmentTarget.getAttachedOrCreate(player, GOT_NOTE)) {
			AttachmentTarget.setAttached(player, GOT_NOTE, true);
		}
	}
}

