import net.minecraft.core.component.DataComponentMap;
import net.minecraft.core.component.DataComponentType;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;

class Injected {
	static boolean has(DataComponentMap.Builder builder, DataComponentType<?> type) {
		return builder.contains(type);
	}

	static String creator(ItemStack stack) {
		return stack.getItem().getCreatorNamespace(stack) + stack.getCreatorNamespace();
	}

	static float power(BlockState state, Level level, BlockPos pos) {
